import bpy
for o in bpy.context.scene.objects:
    mats=[s.material.name if s.material else None for s in o.material_slots]
    mods=[f"{m.name}({m.type})" for m in o.modifiers]
    cp={k:(v if isinstance(v,(int,float,str)) else str(v)) for k,v in o.items() if not k.startswith('_')}
    print(f"name={o.name} | type={o.type} | loc={tuple(round(x,4) for x in o.location)} | rot({o.rotation_mode})={tuple(round(x,4) for x in o.rotation_euler)} | scale={tuple(round(x,4) for x in o.scale)} | dims={tuple(round(x,4) for x in o.dimensions)} | parent={o.parent.name if o.parent else None} | materials={mats} | modifiers={mods} | custom={cp}")

